inline void Segment::loadPalette(uint8_t pal) {
  if (pal == 0) pal = _default_palette;
  CRGB prim(R(colors[0]), G(colors[0]), B(colors[0])), sec(R(colors[1]), G(colors[1]), B(colors[1])), ter(R(colors[2]), G(colors[2]), B(colors[2]));
  switch (pal) {
    case 0: _currentPalette = PartyColors_gc22; break;
    case 1: _currentPalette = CRGBPalette16(CHSV(random8(), random8(160, 255), random8(128, 255)), CHSV(random8(), random8(160, 255), random8(128, 255)),
                                            CHSV(random8(), random8(160, 255), random8(128, 255)), CHSV(random8(), random8(160, 255), random8(128, 255))); break;
    case 2: _currentPalette = CRGBPalette16(prim); break;
    case 3: _currentPalette = CRGBPalette16(prim, prim, sec, sec); break;
    case 4: _currentPalette = CRGBPalette16(ter, sec, prim); break;
    case 5:
      if (colors[2]) _currentPalette = CRGBPalette16(prim,prim,prim,prim,prim,sec,sec,sec,sec,sec,ter,ter,ter,ter,ter,prim);
      else           _currentPalette = CRGBPalette16(prim,prim,prim,prim,prim,prim,prim,prim,sec,sec,sec,sec,sec,sec,sec,sec);
      break;
    default:
      if (pal < 13) _currentPalette = *fastledPalettes[pal - 6];
      else if (pal < 13 + 59) {
        uint8_t tcp[72] = {0}; const uint8_t* src = gGradientPalettes[pal - 13];          // entries are 4 bytes (index,r,g,b), the last one has index 255
        for (uint8_t e = 0; e < 18; e++) { memcpy(tcp + 4 * e, src + 4 * e, 4); if (src[4 * e] == 255) break; }
        _currentPalette.loadDynamicGradientPalette(tcp);
      }
      else _currentPalette = PartyColors_gc22;
      break;
  }
}

struct WfxDef { const char* name; void (*fn)(); const char* meta; };

// ---------------- running an effect
// 1) wfxSelect()  when the effect changes (resets the effect memory, reads WLED's default settings of the effect)
// 2) wfxFrame()   every frame: points the segment at your LED buffer and calls the effect
static inline const char* wfxField(const char* meta, uint8_t n) {      // start of the n-th ';' separated field
  const char* p = meta;
  while (n && *p) { if (*p == ';') n--; p++; }
  return p;
}
static inline uint8_t wfxColorSlots(const WfxDef& d) {                   // how many colour slots the effect shows in WLED's UI
  const char* p = wfxField(d.meta, 1); if (!*p || *p == ';') return 0;
  uint8_t n = 1; for (; *p && *p != ';'; p++) if (*p == ',') n++; return n;
}
static inline void wfxSelect(uint8_t slot, const WfxDef& d) {
  Segment& s = gSegs[slot]; gCur = &s;
  s.resetRuntime();
  s.speed = 128; s.intensity = 128; s.custom1 = 128; s.custom2 = 128; s.custom3 = 16;
  s.check1 = s.check2 = s.check3 = false; s.palette = 0; s._default_palette = 0; s.paletteBlend = 0;
  const char* def = wfxField(d.meta, 4);                                  // "sx=24,ix=128,c1=..,pal=11,o1=1"
  while (*def) {
    const char* e = def; while (*e && *e != ',') e++;
    const char* eq = (const char*)memchr(def, '=', e - def);
    if (eq) {
      int v = atoi(eq + 1); size_t kl = eq - def;
      if (kl == 2 && !strncmp(def, "sx", 2)) s.speed = v;
      else if (kl == 2 && !strncmp(def, "ix", 2)) s.intensity = v;
      else if (kl == 2 && !strncmp(def, "c1", 2)) s.custom1 = v;
      else if (kl == 2 && !strncmp(def, "c2", 2)) s.custom2 = v;
      else if (kl == 2 && !strncmp(def, "c3", 2)) s.custom3 = v & 31;
      else if (kl == 2 && !strncmp(def, "o1", 2)) s.check1 = v;
      else if (kl == 2 && !strncmp(def, "o2", 2)) s.check2 = v;
      else if (kl == 2 && !strncmp(def, "o3", 2)) s.check3 = v;
      else if (kl == 3 && !strncmp(def, "pal", 3)) s.palette = v;
    }
    def = *e ? e + 1 : e;
  }
  s.baseSpeed = s.speed;
}
static inline void wfxFrame(uint8_t slot, const WfxDef& d, CRGB* buf, uint16_t n, uint8_t w, uint8_t h, uint16_t (*xymap)(int, int),
                            uint8_t padSpeed, uint8_t hue, uint32_t now) {
  Segment& s = gSegs[slot]; gCur = &s;
  s.target = buf; s.len = n; s.w = w; s.h = h; s.xymap = xymap;
  strip.now = now; strip.isMatrix = (h > 1);
  CRGB c0 = CHSV(hue, 255, 255), c1 = CRGB::Black, c2 = CRGB::Black;
  if (wfxColorSlots(d) >= 3) { c1 = CHSV(hue + 85, 255, 255); c2 = CHSV(hue + 170, 255, 255); }
  s.colors[0] = RGBW32(c0.r, c0.g, c0.b, 0); s.colors[1] = RGBW32(c1.r, c1.g, c1.b, 0); s.colors[2] = RGBW32(c2.r, c2.g, c2.b, 0);
  s.loadPalette(s.palette);
  s.speed = (uint8_t)min<unsigned>(255, ((unsigned)s.baseSpeed * (padSpeed + 16u)) / 144u);   // pad speed 128 = the effect's normal speed
  if (s.vLength() < 4) { s.fill(s.colors[0]); s.call++; s.target = nullptr; return; }   // WLED's effects need a few LEDs (some divide by the length)
  d.fn();
  s.call++;
  s.target = nullptr;
}

